import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Vector3 } = THREE;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const items = config.textContent ?? visualSpec.textContent ?? [];
  const ownedGeometries = [];
  const ownedMaterials = [];
  const loadedTextures = [];
  const primitiveResults = [];
  const timelines = [];
  let disposed = false;

  const root = new Group();
  root.name = config.id ?? 'features-card-1';
  root.userData.handlers = {};

  const createGradientMaterial = () => {
    const material = new MeshBasicNodeMaterial();
    const cardUv = uv();
    const top = new THREE.Color(colors.ink);
    const bottom = new THREE.Color(colors.surface);
    const blend = smoothstep(0.04, 0.96, cardUv.y);

    material.colorNode = mix(
      vec3(top.r, top.g, top.b),
      vec3(bottom.r, bottom.g, bottom.b),
      blend
    );
    material.toneMapped = false;
    ownedMaterials.push(material);
    return material;
  };

  const createSolidMaterial = (color, opacity = 1) => {
    const material = new MeshBasicNodeMaterial({
      color,
      transparent: opacity < 1,
      opacity
    });
    material.toneMapped = false;
    ownedMaterials.push(material);
    return material;
  };

  const addPlane = (width, height, z, material, name) => {
    const geometry = new PlaneGeometry(width, height);
    ownedGeometries.push(geometry);
    const mesh = new Mesh(geometry, material);
    mesh.position.z = z;
    mesh.name = name;
    root.add(mesh);
    return mesh;
  };

  const backdrop = addPlane(
    2.85,
    1.9,
    -0.04,
    createGradientMaterial(),
    'engineered-gradient-surface'
  );

  const innerFrame = addPlane(
    2.66,
    1.7,
    -0.025,
    createSolidMaterial(colors.ink, 0.58),
    'ink-inner-frame'
  );

  const accentBar = addPlane(
    0.055,
    1.25,
    0.035,
    createSolidMaterial(colors.accent),
    'signal-red-accent'
  );
  accentBar.position.x = -1.17;

  const paperRule = addPlane(
    0.82,
    0.018,
    0.04,
    createSolidMaterial(colors.paper, 0.72),
    'paper-rule'
  );
  paperRule.position.set(-0.62, -0.39, 0);

  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: item.role === 'label' ? 2.5 : 0
    });

    textObject.name = item.role ? `text-${item.role}` : 'text-content';
    textObject.position.set(-0.98, 0.12, 0.06);
    root.add(textObject);
  }

  const imageUrl = config.imageUrl ?? visualSpec.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose();
        return;
      }

      loadedTextures.push(texture);

      const imageMaterial = new MeshBasicNodeMaterial({
        map: texture,
        transparent: true,
        opacity: 0.34
      });
      imageMaterial.toneMapped = false;
      ownedMaterials.push(imageMaterial);

      const imageGeometry = new PlaneGeometry(1.42, 1.42);
      ownedGeometries.push(imageGeometry);

      const imageMesh = new Mesh(imageGeometry, imageMaterial);
      imageMesh.name = 'isolated-atelier-image';
      imageMesh.position.set(0.52, 0.02, 0.025);
      imageMesh.rotation.z = -0.035;
      root.add(imageMesh);
    }).catch(() => {});
  }

  const enterTimeline = gsap.timeline({ paused: true });
  enterTimeline
    .fromTo(
      root.scale,
      { x: 0.97, y: 0.97, z: 0.97 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
    )
    .fromTo(
      root,
      { position: new Vector3(0, -0.16, 0), },
      { position: new Vector3(0, 0, 0), duration: 0.7, ease: 'power3.out' },
      '<'
    );

  timelines.push(enterTimeline);
  enterTimeline.play();

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (!primitive?.name || typeof ctx.primitives?.[primitive.name] !== 'function') {
      continue;
    }

    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const result of primitiveResults) {
      if (result?.cleanup) result.cleanup();
    }

    root.traverse((object) => {
      if (object.userData?.cleanup && object.userData.cleanup !== root.userData.cleanup) {
        object.userData.cleanup();
      }
    });

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    for (const texture of loadedTextures) {
      texture.dispose?.();
    }

    root.clear();
  };

  return root;
}
